"""Exact planar failure probability by counting projective directions.

A seed a in F_p^2 fails on the typical set T exactly when <a, x - y> = 0 for
some pair of distinct typical words, i.e. when a lies on the line orthogonal
to a difference direction.  Proportional differences define the same line, and
two distinct lines through the origin meet only at the origin, so the bad
seeds form a pencil of d lines of total size 1 + d(p-1), where d is the number
of distinct projective directions of the difference set.

Complexity: O(t^2 log p) to count directions (one modular inverse per pair),
versus O(p^2 t) for brute-force enumeration of the seed space.
"""

from __future__ import annotations

from fractions import Fraction
from typing import Sequence, Set, Tuple

Point = Tuple[int, int]


def canonical_direction(z: Point, p: int) -> Point:
    """Scale a nonzero vector so its first nonzero coordinate is 1."""
    pivot = z[0] if z[0] % p else z[1]
    inv = pow(pivot, p - 2, p)                    # Fermat inverse in F_p
    return ((z[0] * inv) % p, (z[1] * inv) % p)


def projective_direction_count(typical: Sequence[Point], p: int) -> int:
    """The number d of distinct projective directions of the difference set."""
    reps: Set[Point] = set()
    for i, x in enumerate(typical):
        for y in typical[i + 1:]:
            z = ((x[0] - y[0]) % p, (x[1] - y[1]) % p)
            if z != (0, 0):
                reps.add(canonical_direction(z, p))
    return len(reps)


def exact_failure_probability(typical: Sequence[Point], p: int) -> Fraction:
    """The exact probability (1 + d(p-1))/p^2 that a uniform seed fails."""
    d = projective_direction_count(typical, p)
    if d == 0:
        return Fraction(0)
    return Fraction(1 + d * (p - 1), p * p)


def union_bound(typical: Sequence[Point], p: int) -> Fraction:
    """The classical union bound t(t-1)/p, for comparison."""
    t = len(typical)
    return min(Fraction(t * (t - 1), p), Fraction(1))


def brute_force_failure_probability(typical: Sequence[Point], p: int) -> Fraction:
    """Exhaustive enumeration of all p^2 seeds, used to certify the formula."""
    bad = 0
    for a0 in range(p):
        for a1 in range(p):
            seen = set()
            for x in typical:
                h = (a0 * x[0] + a1 * x[1]) % p
                if h in seen:
                    bad += 1
                    break
                seen.add(h)
    return Fraction(bad, p * p)
